{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-By2Wn9/src/address.js","content":"/**
 * Cell address parsing and ordering. An address is one or two letters
 * naming a column (A..Z, then AA..ZZ) and one to three digits naming a
 * row of at least 1.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parses a word as a cell address. Returns null when the word's shape
 * does not match the address grammar (wrong letter/digit counts or a
 * zero row), which callers treat as "outside the addressable range".
 */
export function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const col = columnToNumber(m[1])
  const canonical = m[1].toUpperCase() + String(row)
  return { col, row, canonical }
}

function columnToNumber(letters) {
  const upper = letters.toUpperCase()
  let n = 0
  for (const ch of upper) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** Ascending column then ascending row, per the sheet's print order. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}

/**
 * Expands a range between two addresses (given in either corner order)
 * into every covered address, ascending column then ascending row.
 */
export function expandRange(a, b) {
  const minCol = Math.min(a.col, b.col)
  const maxCol = Math.max(a.col, b.col)
  const minRow = Math.min(a.row, b.row)
  const maxRow = Math.max(a.row, b.row)
  const result = []
  for (let col = minCol; col <= maxCol; col++) {
    for (let row = minRow; row <= maxRow; row++) {
      result.push({ col, row, canonical: numberToColumn(col) + String(row) })
    }
  }
  return result
}

function numberToColumn(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}
"}

