{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-By2Wn9/src/sheet.js","content":"/**
 * Parses the sheet text into a map of canonical address -> raw content.
 */

import { parseAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
    this.name = 'SheetError'
  }
}

/**
 * Parses the sheet source into a Map from canonical address (e.g. "A1")
 * to its raw content string. Throws SheetError with a fully-formed
 * message (including the line number) on the first invalid or
 * duplicate address.
 */
export function parseSheet(source) {
  const lines = source.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const stripped = line.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const m = /^([^ \t]+)([ \t]?)(.*)$/s.exec(stripped)
    const addressWord = m[1]
    const rest = m[2] === '' ? '' : stripped.slice(addressWord.length + 1)

    const addr = parseAddress(addressWord)
    if (!addr) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${addressWord}`)
    }
    if (cells.has(addr.canonical)) {
      throw new SheetError(`error: line ${lineNo}: cell ${addr.canonical} is declared twice`)
    }
    cells.set(addr.canonical, rest)
  }
  return cells
}
"}

