 * Recursive-descent parser for formula bodies, producing an AST.
 *
 * Node shapes:
 *   { type: 'num', value }
 *   { type: 'bool', value }
 *   { type: 'ref', address }               -- address is the raw word, upper-cased
 *   { type: 'range', from, to }            -- only ever appears as a call argument
 *   { type: 'call', name, args }           -- name upper-cased, args are expr|range
 *   { type: 'unary', op, operand }
 *   { type: 'binop', op, left, right }
 */

import { tokenize, GrammarError } from './tokenizer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Cursor {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }
  next() {
    return this.tokens[this.pos++]
  }
  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new GrammarError(`expected ${type}`)
    return t
  }
  atEnd() {
    return this.pos >= this.tokens.length
  }
}

/** Parses a formula body (without the leading `=`) into an AST. */
export function parseFormula(body) {
  const tokens = tokenize(body)
  const cursor = new Cursor(tokens)
  const expr = parseComparison(cursor)
  if (!cursor.atEnd()) throw new GrammarError('trailing tokens')
  return expr
}

function parseComparison(cursor) {
  let left = parseAdditive(cursor)
  while (cursor.peek() && COMPARISON_OPS.has(cursor.peek().type)) {
    const op = cursor.next().type
    const right = parseAdditive(cursor)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parseAdditive(cursor) {
  let left = parseMultiplicative(cursor)
  while (cursor.peek() && (cursor.peek().type === '+' || cursor.peek().type === '-')) {
    const op = cursor.next().type
    const right = parseMultiplicative(cursor)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parseMultiplicative(cursor) {
  let left = parsePower(cursor)
  while (cursor.peek() && (cursor.peek().type === '*' || cursor.peek().type === '/')) {
    const op = cursor.next().type
    const right = parsePower(cursor)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parsePower(cursor) {
  const left = parseUnary(cursor)
  if (cursor.peek() && cursor.peek().type === '^') {
    cursor.next()
    const right = parsePower(cursor)
    return { type: 'binop', op: '^', left, right }
  }
  return left
}

function parseUnary(cursor) {
  const t = cursor.peek()
  if (t && (t.type === '+' || t.type === '-')) {
    cursor.next()
    const operand = parseUnary(cursor)
    return { type: 'unary', op: t.type, operand }
  }
  return parseAtom(cursor)
}

function parseAtom(cursor) {
  const t = cursor.next()
  if (!t) throw new GrammarError('unexpected end of formula')

  if (t.type === 'number') {
    return { type: 'num', value: Number(t.text) }
  }

  if (t.type === '(') {
    const expr = parseComparison(cursor)
    cursor.expect(')')
    return expr
  }

  if (t.type === 'word') {
    const upper = t.text.toUpperCase()
    if (cursor.peek() && cursor.peek().type === '(') {
      cursor.next()
      const args = parseArgList(cursor)
      cursor.expect(')')
      return { type: 'call', name: upper, args }
    }
    if (upper === 'TRUE') return { type: 'bool', value: true }
    if (upper === 'FALSE') return { type: 'bool', value: false }
    return { type: 'ref', address: upper }
  }

  throw new GrammarError(`unexpected token ${t.type}`)
}

