 * The four value kinds a cell can hold, plus the conversions and
 * formatting rules that arithmetic, comparisons and printing need.
 */

export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function num(value) {
  return { kind: 'number', value }
}
export function text(value) {
  return { kind: 'text', value }
}
export function bool(value) {
  return { kind: 'bool', value }
}
export function err(token) {
  return { kind: 'error', value: token }
}

export function isError(value) {
  return value.kind === 'error'
}

/** Rounds to ten significant digits, formatted as JavaScript would print it. */
export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return rounded === 0 ? '0' : rounded.toString()
}

export function formatValue(value) {
  switch (value.kind) {
    case 'number':
      return formatNumber(value.value)
    case 'error':
      return value.value
    case 'bool':
      return value.value ? 'TRUE' : 'FALSE'
    case 'text':
      return value.value
    default:
      throw new Error(`unknown value kind ${value.kind}`)
  }
}

/**
 * Reads a value as a number for an arithmetic position: numbers pass
 * through, booleans become 1 or 0, and text becomes `#VALUE!`.
 */
export function toArithmeticNumber(value) {
  if (value.kind === 'number') return value.value
  if (value.kind === 'bool') return value.value ? 1 : 0
  return null
}

/** Wraps a raw arithmetic result, turning any non-finite result into `#DIV/0!`. */
export function finiteOrDivError(n) {
  return Number.isFinite(n) ? num(n) : err('#DIV/0!')
}

const KIND_RANK = { number: 0, text: 1, bool: 2 }

/** -1, 0 or 1 per the cross-kind ordering: numbers < text < booleans. */
export function compareValues(a, b) {
  if (a.kind !== b.kind) return KIND_RANK[a.kind] - KIND_RANK[b.kind] < 0 ? -1 : 1
  if (a.kind === 'number') return a.value - b.value
  if (a.kind === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  // bool: false below true
  return (a.value ? 1 : 0) - (b.value ? 1 : 0)
}
"}

