 * Evaluates cells, resolving formulas, references, ranges and function
 * calls into values, with cycle detection across the whole sheet.
 */

import { parseAddress, expandRange } from './address.js'
import { parseFormula } from './parser.js'
import { GrammarError } from './tokenizer.js'
import { parseLiteral } from './literal.js'
import { num, bool, err, isError, toArithmeticNumber, finiteOrDivError, compareValues } from './value.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const AGGREGATE_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.visiting = new Set()
  }

  /** Evaluates the cell at a canonical address (e.g. "A1"), memoized. */
  getValue(address) {
    if (this.cache.has(address)) return this.cache.get(address)
    if (this.visiting.has(address)) return err('#CYCLE!')

    this.visiting.add(address)
    const content = this.cells.has(address) ? this.cells.get(address) : ''
    const value = this.evalContent(content)
    this.visiting.delete(address)
    this.cache.set(address, value)
    return value
  }

  evalContent(content) {
    if (!content.startsWith('=')) return parseLiteral(content)
    let ast
    try {
      ast = parseFormula(content.slice(1))
    } catch (e) {
      if (e instanceof GrammarError) return err('#ERR!')
      throw e
    }
    return this.evalNode(ast)
  }

  evalNode(node) {
    switch (node.type) {
      case 'num':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'ref':
        return this.evalRef(node.address)
      case 'unary':
        return this.evalUnary(node)
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`cannot evaluate node of type ${node.type}`)
    }
  }

  evalRef(address) {
    const addr = parseAddress(address)
    if (!addr) return err('#REF!')
    return this.getValue(addr.canonical)
  }

  evalUnary(node) {
    const operand = this.evalNode(node.operand)
    if (isError(operand)) return operand
    const n = toArithmeticNumber(operand)
    if (n === null) return err('#VALUE!')
    return finiteOrDivError(node.op === '-' ? -n : +n)
  }

  evalBinop(node) {
    const left = this.evalNode(node.left)
    const right = this.evalNode(node.right)
    if (isError(left)) return left
    if (isError(right)) return right

    if (COMPARISON_OPS.has(node.op)) {
      const c = compareValues(left, right)
      const result =
        node.op === '=' ? c === 0
        : node.op === '<>' ? c !== 0
        : node.op === '<' ? c < 0
        : node.op === '<=' ? c <= 0
        : node.op === '>' ? c > 0
        : c >= 0
      return bool(result)
    }

    const ln = toArithmeticNumber(left)
    if (ln === null) return err('#VALUE!')
    const rn = toArithmeticNumber(right)
    if (rn === null) return err('#VALUE!')

    switch (node.op) {
      case '+':
        return finiteOrDivError(ln + rn)
      case '-':
        return finiteOrDivError(ln - rn)
      case '*':
        return finiteOrDivError(ln * rn)
      case '/':
        return finiteOrDivError(ln / rn)
      case '^':
        return finiteOrDivError(Math.pow(ln, rn))
      default:
        throw new Error(`unknown operator ${node.op}`)
    }
  }

  /** Evaluates a call argument (expr or range) into a flat list of values. */
  expandArg(argNode) {
    if (argNode.type !== 'range') return [this.evalNode(argNode)]
    const from = parseAddress(argNode.from)
    const to = parseAddress(argNode.to)
    if (!from || !to) return [err('#REF!')]
    return expandRange(from, to).map((c) => this.getValue(c.canonical))
  }

  /** Evaluates every argument (ranges expanded), always left to right. */
  expandArgs(argNodes) {
    const values = []
    for (const argNode of argNodes) values.push(...this.expandArg(argNode))
    return values
  }

  /** A single scalar value from an argument that must not be a multi-cell range. */
  singleArgValue(argNode) {
    const values = this.expandArg(argNode)
    const firstError = values.find(isError)
    if (firstError) return firstError
    if (values.length !== 1) return err('#VALUE!')
    return values[0]
  }

  evalCall(node) {
    const { name, args } = node

    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      const cond = this.singleArgValue(args[0])
      if (isError(cond)) return cond
      const truthy = this.readCondition(cond)
      if (isError(truthy)) return truthy
      return this.singleArgValue(truthy ? args[1] : args[2])
    }

    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      const value = this.singleArgValue(args[0])
      if (isError(value)) return value
      const n = toArithmeticNumber(value)
      if (n === null) return err('#VALUE!')
      return finiteOrDivError(Math.abs(n))
    }

    if (AGGREGATE_FUNCTIONS.has(name)) {
      if (args.length < 1) return err('#ERR!')
      const values = this.expandArgs(args)
      const firstError = values.find(isError)
      if (firstError) return firstError
      return this.evalAggregate(name, values)
    }

    return err('#NAME?')
  }

  readCondition(value) {
    if (value.kind === 'bool') return value.value
    if (value.kind === 'number') return value.value !== 0
    return err('#VALUE!')
  }

  evalAggregate(name, values) {
    if (name === 'COUNT') {
      return num(values.filter((v) => v.kind === 'number').length)
    }

    const numbers = []
    for (const v of values) {
      const n = toArithmeticNumber(v)
      if (n === null) return err('#VALUE!')
      numbers.push(n)
    }

    switch (name) {
      case 'SUM':
        return finiteOrDivError(numbers.reduce((a, b) => a + b, 0))
      case 'AVG':
        return finiteOrDivError(numbers.reduce((a, b) => a + b, 0) / numbers.length)
      case 'MIN':
        return finiteOrDivError(Math.min(...numbers))
      case 'MAX':
        return finiteOrDivError(Math.max(...numbers))
      default:
        throw new Error(`unknown aggregate ${name}`)
    }
  }
}
"}

