import { parseFormula } from './parser.js'
import { GrammarError } from './tokenizer.js'

/** Returns the canonical addresses a cell's content names, in print order. */
export function directDeps(content) {
  if (!content.startsWith('=')) return []
  let ast
  try {
    ast = parseFormula(content.slice(1))
  } catch (e) {
    if (e instanceof GrammarError) return []
    throw e
  }

  const found = new Map()
  collect(ast, found)
  return [...found.values()].sort(compareAddresses).map((a) => a.canonical)
}

