import { GrammarError } from './tokenizer.js'

/** Returns the canonical addresses a cell's content names, in print order. */
export function directDeps(content) {
  if (!content.startsWith('=')) return []
  let ast
  try {
    ast = parseFormula(content.slice(1))
  } catch (e) {
    if (e instanceof GrammarError) return []
    throw e
  }

  const found = new Map()
  collect(ast, found)
  return [...found.values()].sort(compareAddresses).map((a) => a.canonical)
}

function collect(node, found) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'ref': {
      const a = parseAddress(node.address)
      if (a) found.set(a.canonical, a)
      return
    }
    case 'range': {
      const from = parseAddress(node.from)
      const to = parseAddress(node.to)
      if (from && to) {
        for (const c of expandRange(from, to)) found.set(c.canonical, c)
      }
      return
    }
    case 'unary':
      collect(node.operand, found)
      return
    case 'binop':
      collect(node.left, found)
      collect(node.right, found)
      return
    case 'call':
      for (const arg of node.args) collect(arg, found)
      return
    default:
      throw new Error(`cannot collect deps for node of type ${node.type}`)
  }
}
